// Command harnaas manages a project's AI-harness assets as a declared,
// versioned dependency of the repository.
//
// This file owns the whole process contract: it is the only component that
// prints an error, the only one that chooses an exit code, and the only one
// that decides how a signal terminates the process. Commands return errors;
// what those errors look like on the terminal is decided here, once.
package main

import (
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/signal"
	"runtime"
	"strings"
	"syscall"
	"time"

	"github.com/harnaas/harnaas/cmd/harnaas/cli"
	"github.com/harnaas/harnaas/cmd/harnaas/cli/versioninfo"
	"github.com/harnaas/harnaas/internal/procsignal"
	"github.com/spf13/cobra"
)

// The exit-code contract. Every status harnaas can produce is listed here, and
// a new one must not be introduced without a documented meaning.
//
//   - exitSuccess       the command completed and found nothing to report.
//   - exitFailure       any runtime failure: bad configuration, I/O, network.
//   - exitLintFindings  reserved: `lint` ran its checks to completion and
//     reported at least one error-severity finding.
//
// exitLintFindings exists so a CI job can tell "lint crashed" from "lint worked
// and your harness has drifted" — the distinction lint exists to make. It is
// reserved for that single meaning: no command other than `lint` may return it,
// and a lint run that fails partway through exits exitFailure like any other
// runtime failure. Nothing in this binary emits it yet; `lint` itself arrives
// with add-harnaas-lint, and reportError below never produces it.
//
// Termination by signal is not in this list because it is not an exit at all:
// see dieFromSignal, which re-raises the signal and only falls back to
// 128-plus-signal-number where re-raising is unsupported.
const (
	exitSuccess      = 0
	exitFailure      = 1
	exitLintFindings = 2
)

// forceQuitGrace is how long dieFromSignal waits for a re-raised signal to be
// delivered. Delivery ends the process well before this elapses; the wait only
// exists so a platform that silently drops the re-raise still reaches the
// fallback exit instead of hanging.
const forceQuitGrace = 500 * time.Millisecond

func main() {
	// Resolve version and commit before anything reads them — the root command
	// copies Version into its own field as it is built.
	versioninfo.Load()

	os.Exit(run())
}

// run executes the command tree and returns the process exit code. It exists
// as a separate function so the deferred cancel actually runs; main's os.Exit
// would skip it.
func run() int {
	ctx, cancel := context.WithCancel(context.Background())
	defer cancel()

	watchSignals(cancel, os.Stderr)

	root := cli.NewRootCmd()

	// ExecuteContextC returns the deepest command cobra matched, which is the
	// one whose usage a positional-argument error should show.
	executed, err := root.ExecuteContextC(ctx)
	if err == nil {
		return exitSuccess
	}

	if sig := terminatingSignal(err); sig != nil {
		cancel()
		dieFromSignal(sig)
	}

	return reportError(root.ErrOrStderr(), root, executed, err)
}

// watchSignals installs the two-stage handler. The first signal cancels the
// root context so in-flight work unwinds cleanly and prints a notice; because
// signal.Notify has disabled Go's default "signal terminates the process"
// behaviour, a second read is what keeps a further Ctrl-C from being swallowed
// during a slow or stuck shutdown. The caught signal is recorded so the
// eventual termination re-raises that same signal rather than assuming an
// interrupt.
func watchSignals(cancel context.CancelFunc, notice io.Writer) {
	sigChan := make(chan os.Signal, 1)
	signals := []os.Signal{os.Interrupt}
	if runtime.GOOS != "windows" {
		signals = append(signals, syscall.SIGTERM)
	}
	signal.Notify(sigChan, signals...)

	go func() {
		sig := <-sigChan
		procsignal.Store(sig)
		fmt.Fprintln(notice, forceQuitNotice(sig))
		cancel()
		<-sigChan
		dieFromSignal(sig)
	}()
}

// forceQuitNotice is the advisory text for a first signal. It distinguishes an
// interrupt the user typed from a termination signal a supervisor sent, because
// the two want different explanations, and it leads with a blank line so the
// notice does not land on top of a half-written progress line.
func forceQuitNotice(sig os.Signal) string {
	if sig == os.Interrupt {
		return "\nInterrupting… press Ctrl-C again to force quit."
	}
	return "\nReceived termination signal, shutting down… signal again to force quit."
}

// terminatingSignal reports the signal that cancelled the root context, or nil
// if the cancellation was not signal-driven.
//
// The gate is deliberately on a signal having been recorded rather than on the
// error type alone: a context.Canceled that arose without a signal — an
// internally cancelled sub-context, say — is a genuine failure and must be
// reported as one, not dressed up as a user abort that would also wrongly break
// an enclosing shell loop.
func terminatingSignal(err error) os.Signal {
	if !errors.Is(err, context.Canceled) {
		return nil
	}
	return procsignal.Load()
}

// dieFromSignal terminates the process as if it had been killed by sig, rather
// than exiting normally.
//
// The distinction matters to an interactive shell: it aborts a
// `while true; do harnaas …; done` loop only when the child is *killed by*
// SIGINT. A plain exit with status 130 is an ordinary exit, so the loop keeps
// respawning harnaas and the user's Ctrl-C never escapes it. Re-raising the
// actual signal also keeps a SIGTERM shutdown reporting the conventional 143.
//
// The signal is reset to its default disposition, re-raised at this process,
// and given a moment to arrive. Where the re-raise cannot be delivered — on
// Windows, where signal-to-self is unsupported — the conventional
// 128-plus-signal-number exit is the fallback, so the process never hangs.
func dieFromSignal(sig os.Signal) {
	signal.Reset(sig)
	if p, err := os.FindProcess(os.Getpid()); err == nil {
		if err := p.Signal(sig); err == nil {
			time.Sleep(forceQuitGrace)
		}
	}
	os.Exit(exitCodeForSignal(sig))
}

// exitCodeForSignal maps a signal to the conventional 128-plus-signal-number
// exit code — 130 for SIGINT, 143 for SIGTERM — falling back to an interrupt's
// 130 for a signal carrying no numeric value on this platform.
func exitCodeForSignal(sig os.Signal) int {
	if s, ok := sig.(syscall.Signal); ok {
		return 128 + int(s)
	}
	return 128 + int(syscall.SIGINT)
}

// reportError renders err according to the error contract and returns the exit
// code the process should use. It is the single place that decides what a
// failure looks like on the terminal.
//
// root is the command tree's root and executed is the deepest command cobra
// matched; the two differ exactly when a subcommand's own validator failed,
// which is when the subcommand's usage — not the root's — is the useful one.
func reportError(out io.Writer, root, executed *cobra.Command, err error) int {
	var printed *cli.AlreadyPrintedError

	switch {
	case errors.As(err, &printed):
		// The command already wrote a friendly explanation. Printing anything
		// here would restate it in a less useful form.
	case isUnknownCommandOrFlagError(err):
		writeUsageAndError(out, root, err)
	case isPositionalArgError(err):
		writeUsageAndError(out, executed, err)
	default:
		fmt.Fprintln(out, err)
	}

	return exitFailure
}

// isUnknownCommandOrFlagError reports whether err is cobra's complaint about a
// verb or flag it does not recognise, which is a usage problem rather than a
// runtime one.
func isUnknownCommandOrFlagError(err error) bool {
	msg := err.Error()
	return strings.Contains(msg, "unknown command") || strings.Contains(msg, "unknown flag")
}

// isPositionalArgError reports whether err looks like a cobra positional-
// argument validator failure. Cobra's stock validators — ExactArgs, NoArgs,
// MinimumNArgs, MaximumNArgs, RangeArgs — all surface messages containing
// "arg(s)", and that substring appears in none of cobra's other error paths nor
// in harnaas's own errors, so it is a stable discriminator that does not reach
// into cobra internals.
func isPositionalArgError(err error) bool {
	return strings.Contains(err.Error(), "arg(s)")
}

// writeUsageAndError prints the command's usage before the error, so the reader
// sees what was expected and only then what went wrong.
func writeUsageAndError(out io.Writer, cmd *cobra.Command, err error) {
	if cmd == nil {
		fmt.Fprintln(out, err)
		return
	}
	fmt.Fprint(out, cmd.UsageString())
	fmt.Fprintf(out, "\nError: invalid usage: %v\n", err)
}

package main

import (
	"bytes"
	"context"
	"errors"
	"fmt"
	"io"
	"os"
	"os/exec"
	"runtime"
	"syscall"
	"testing"

	"github.com/harnaas/harnaas/cmd/harnaas/cli"
	"github.com/harnaas/harnaas/internal/procsignal"
	"github.com/spf13/cobra"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// dieFromSignalEnvVar, when set on a re-executed test binary, makes TestMain
// call dieFromSignal with the named signal instead of running the suite. The
// parent then inspects how the child died — the only way to exercise real
// process death without killing the test runner.
const dieFromSignalEnvVar = "HARNAAS_TEST_DIE_FROM_SIGNAL"

func TestMain(m *testing.M) {
	if name := os.Getenv(dieFromSignalEnvVar); name != "" {
		sig := os.Signal(syscall.SIGINT)
		if name == "TERM" {
			sig = syscall.SIGTERM
		}
		// dieFromSignal returns only when the re-raise could not be delivered,
		// so the fallback here mirrors its own.
		dieFromSignal(sig)
		os.Exit(exitCodeForSignal(sig))
	}
	os.Exit(m.Run())
}

// nonNumericSignal is an os.Signal that is not a syscall.Signal, exercising
// exitCodeForSignal's fallback branch.
type nonNumericSignal struct{}

func (nonNumericSignal) String() string { return "non-numeric" }
func (nonNumericSignal) Signal()        {}

// TestDieFromSignalTerminatesBySignal is the regression guard for the headline
// behaviour: a shell aborts a `while true; do harnaas …; done` loop only when
// the child is killed by the signal, not when it exits normally with code 130.
// Simplifying dieFromSignal back to a plain os.Exit(130) would leave the exit
// code looking right while silently breaking loop escape; this catches exactly
// that by re-executing the test binary and asserting how it died.
func TestDieFromSignalTerminatesBySignal(t *testing.T) {
	t.Parallel()
	if runtime.GOOS == "windows" {
		t.Skip("signal-to-self and kill-by-signal reporting do not exist on Windows")
	}

	tests := []struct {
		name string
		env  string
		want syscall.Signal
	}{
		{"SIGINT", "INT", syscall.SIGINT},
		{"SIGTERM", "TERM", syscall.SIGTERM},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			// -test.run=^$ matches no test; TestMain's child branch runs before
			// m.Run and ends the process, so no test actually executes.
			cmd := exec.CommandContext(t.Context(), os.Args[0], "-test.run=^$")
			cmd.Env = append(os.Environ(), dieFromSignalEnvVar+"="+tc.env)

			err := cmd.Run()

			var exitErr *exec.ExitError
			require.ErrorAs(t, err, &exitErr, "child should have died by signal, got err=%v", err)
			ws, ok := exitErr.Sys().(syscall.WaitStatus)
			require.True(t, ok, "no syscall.WaitStatus available: %T", exitErr.Sys())
			require.True(t, ws.Signaled(),
				"child exited normally with code %d; dieFromSignal must re-raise, not os.Exit", ws.ExitStatus())
			assert.Equal(t, tc.want, ws.Signal())
		})
	}
}

// TestExitCodeForSignal locks the 128-plus-signal-number mapping, so a
// "simplification" back to a hardcoded 130 cannot silently regress SIGTERM.
func TestExitCodeForSignal(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		sig  os.Signal
		want int
	}{
		{"interrupt", os.Interrupt, 130},
		{"termination", syscall.SIGTERM, 143},
		{"a signal with no number falls back to the interrupt code", nonNumericSignal{}, 130},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()
			assert.Equal(t, tc.want, exitCodeForSignal(tc.sig))
		})
	}
}

// TestExitCodeTaxonomy pins the documented meanings so a later change cannot
// renumber them, and records that 2 is reserved rather than in use.
func TestExitCodeTaxonomy(t *testing.T) {
	t.Parallel()

	assert.Equal(t, 0, exitSuccess)
	assert.Equal(t, 1, exitFailure)
	assert.Equal(t, 2, exitLintFindings)
}

func TestForceQuitNoticeDistinguishesTheSignal(t *testing.T) {
	t.Parallel()

	assert.Contains(t, forceQuitNotice(os.Interrupt), "Ctrl-C again")
	assert.Contains(t, forceQuitNotice(syscall.SIGTERM), "termination signal")
}

func TestTerminatingSignal(t *testing.T) {
	// Mutates the process-global recorded signal, so no t.Parallel here.
	tests := []struct {
		name     string
		recorded os.Signal
		err      error
		want     os.Signal
	}{
		{
			name:     "a signalled cancellation reports its signal",
			recorded: syscall.SIGTERM,
			err:      context.Canceled,
			want:     syscall.SIGTERM,
		},
		{
			name:     "a cancellation with no signal is an ordinary failure",
			recorded: nil,
			err:      fmt.Errorf("fetch source: %w", context.Canceled),
			want:     nil,
		},
		{
			name:     "an unrelated error is never signal-driven",
			recorded: os.Interrupt,
			err:      errors.New("manifest is missing"),
			want:     nil,
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			procsignal.Reset()
			if tc.recorded != nil {
				procsignal.Store(tc.recorded)
			}
			t.Cleanup(procsignal.Reset)

			assert.Equal(t, tc.want, terminatingSignal(tc.err))
		})
	}
}

// newTestTree builds a root with one subcommand that takes exactly one
// argument, which is enough to reach every branch of the error switch.
func newTestTree() (root, child *cobra.Command) {
	root = cli.NewRootCmd()
	child = &cobra.Command{
		Use:   "demo",
		Short: "a subcommand used only by the entrypoint tests",
		Args:  cobra.ExactArgs(1),
		RunE:  func(*cobra.Command, []string) error { return nil },
	}
	root.AddCommand(child)
	return root, child
}

func TestReportErrorPrintsAnAlreadyPrintedErrorNoFurther(t *testing.T) {
	t.Parallel()

	root, _ := newTestTree()
	cause := errors.New("harnaas.json not found")
	var out bytes.Buffer

	code := reportError(&out, root, root, cli.NewAlreadyPrintedError(cause))

	assert.Equal(t, exitFailure, code, "an already-printed failure still exits non-zero")
	assert.Empty(t, out.String(), "the command already explained this; the entrypoint must add nothing")
}

func TestReportErrorPrintsAPlainErrorExactlyOnce(t *testing.T) {
	t.Parallel()

	root, _ := newTestTree()
	var out bytes.Buffer

	code := reportError(&out, root, root, errors.New("read manifest: permission denied"))

	assert.Equal(t, exitFailure, code)
	assert.Equal(t, "read manifest: permission denied\n", out.String())
}

func TestReportErrorShowsRootUsageForAnUnknownCommandOrFlag(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name string
		err  error
	}{
		{"unknown command", errors.New(`unknown command "instal" for "harnaas"`)},
		{"unknown flag", errors.New("unknown flag: --jsn")},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			root, _ := newTestTree()
			var out bytes.Buffer

			code := reportError(&out, root, root, tc.err)

			assert.Equal(t, exitFailure, code)
			assert.Contains(t, out.String(), root.UsageString())
			assert.Contains(t, out.String(), tc.err.Error())
		})
	}
}

func TestReportErrorShowsTheDeepestSubcommandUsageForAnArgCountError(t *testing.T) {
	t.Parallel()

	root, child := newTestTree()
	var out bytes.Buffer

	code := reportError(&out, root, child, errors.New("accepts 1 arg(s), received 3"))

	assert.Equal(t, exitFailure, code)
	assert.Contains(t, out.String(), child.UsageString())
	assert.NotContains(t, out.String(), root.UsageString(),
		"an arg-count failure belongs to the subcommand, so the root's usage is not the useful one")
}

// TestReportErrorNeverReturnsTheLintFindingsCode holds the negative half of the
// exit-code contract: 2 means lint findings and nothing else, so no error path
// in the entrypoint may produce it.
func TestReportErrorNeverReturnsTheLintFindingsCode(t *testing.T) {
	t.Parallel()

	root, child := newTestTree()
	errs := []error{
		errors.New("read manifest: permission denied"),
		cli.NewAlreadyPrintedError(errors.New("harnaas.json not found")),
		errors.New(`unknown command "instal" for "harnaas"`),
		errors.New("unknown flag: --jsn"),
		errors.New("accepts 1 arg(s), received 3"),
		context.Canceled,
	}
	for _, err := range errs {
		var out bytes.Buffer
		assert.NotEqual(t, exitLintFindings, reportError(&out, root, child, err), "error: %v", err)
	}
}

// TestReportErrorKeepsTheCauseUnwrappable guards the other half of the
// already-printed contract: suppressing the message must not suppress the
// error, so a caller can still inspect what happened.
func TestReportErrorKeepsTheCauseUnwrappable(t *testing.T) {
	t.Parallel()

	cause := errors.New("harnaas.json not found")
	err := error(cli.NewAlreadyPrintedError(cause))

	root, _ := newTestTree()
	var out bytes.Buffer
	reportError(&out, root, root, err)

	assert.ErrorIs(t, err, cause)
}

// TestErrorSwitchClassifiesRealCobraErrors runs the switch over errors cobra
// actually produces, rather than hand-written lookalikes, so a change to
// cobra's wording cannot leave the classifiers silently matching nothing.
func TestErrorSwitchClassifiesRealCobraErrors(t *testing.T) {
	t.Parallel()

	tests := []struct {
		name      string
		args      []string
		wantUsage func(root, child *cobra.Command) *cobra.Command
	}{
		{
			name:      "an unrecognized verb shows the root usage",
			args:      []string{"bogus"},
			wantUsage: func(root, _ *cobra.Command) *cobra.Command { return root },
		},
		{
			name:      "an unrecognized flag shows the root usage",
			args:      []string{"--jsn"},
			wantUsage: func(root, _ *cobra.Command) *cobra.Command { return root },
		},
		{
			name:      "a wrong argument count shows the subcommand usage",
			args:      []string{"demo", "one", "two"},
			wantUsage: func(_, child *cobra.Command) *cobra.Command { return child },
		},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			root, child := newTestTree()
			root.SetOut(io.Discard)
			root.SetErr(io.Discard)
			root.SetArgs(tc.args)

			executed, err := root.ExecuteContextC(t.Context())
			require.Error(t, err)

			var out bytes.Buffer
			code := reportError(&out, root, executed, err)

			assert.Equal(t, exitFailure, code)
			assert.Contains(t, out.String(), tc.wantUsage(root, child).UsageString())
			assert.Contains(t, out.String(), err.Error())
		})
	}
}

// TestRootCommandSuppressesCobrasOwnErrorPrinting proves the entrypoint really
// is the only component that renders an error: cobra must return the failure
// without writing anything itself.
func TestRootCommandSuppressesCobrasOwnErrorPrinting(t *testing.T) {
	t.Parallel()

	root, _ := newTestTree()
	var out, errOut bytes.Buffer
	root.SetOut(&out)
	root.SetErr(&errOut)
	root.SetArgs([]string{"demo"}) // ExactArgs(1) fails

	_, err := root.ExecuteContextC(t.Context())

	require.Error(t, err)
	assert.Empty(t, out.String())
	assert.Empty(t, errOut.String(), "cobra must print neither the error nor the usage block")
}

