package cli

import (
	"go/ast"
	"go/parser"
	"go/token"
	"strings"
	"testing"

	"github.com/spf13/cobra"
	"github.com/stretchr/testify/assert"
	"github.com/stretchr/testify/require"
)

// newLeafCmd builds a subcommand that does nothing, for tests that care about
// how the tree is wired rather than what a command does.
func newLeafCmd(use string) *cobra.Command {
	return &cobra.Command{
		Use:   use,
		Short: "a subcommand used only by the wiring tests",
		Args:  cobra.NoArgs,
		RunE:  func(*cobra.Command, []string) error { return nil },
	}
}

// TestRootDeclaresNoPersistentFlags is the guard on the rule that gives --json
// its meaning: nothing is inherited, so a flag a command accepts is a flag that
// command honours. Adding a persistent flag here — however convenient — would
// make every future verb silently accept it.
func TestRootDeclaresNoPersistentFlags(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	// Cobra registers --help and --version lazily, on Flags() rather than
	// PersistentFlags(); force that to happen so the assertion is made against
	// a fully initialized command.
	root.InitDefaultHelpFlag()
	root.InitDefaultVersionFlag()

	var declared []string
	root.PersistentFlags().VisitAll(func(f *pflagFlag) { declared = append(declared, f.Name) })

	assert.Empty(t, declared,
		"the root must declare no persistent flags; register a flag locally on each command that honours it")
}

// TestJSONFlagIsUnknownOnACommandThatDoesNotDeclareIt is the other half of the
// same rule, observed from the outside: --json is only accepted where it is
// registered, and elsewhere it fails loudly instead of being ignored.
func TestJSONFlagIsUnknownOnACommandThatDoesNotDeclareIt(t *testing.T) {
	t.Parallel()

	root := NewRootCmd()
	renders := newLeafCmd("renders")
	addJSONFlag(renders)
	addCommand(root, renders, groupAssets)
	addCommand(root, newLeafCmd("acts"), groupSetup)

	tests := []struct {
		name    string
		args    []string
		wantErr string
	}{
		{"the command that declares it accepts it", []string{"renders", "--json"}, ""},
		{"a sibling that does not declare it rejects it", []string{"acts", "--json"}, "unknown flag: --json"},
		{"the root rejects it too", []string{"--json"}, "unknown flag: --json"},
	}
	for _, tc := range tests {
		t.Run(tc.name, func(t *testing.T) {
			t.Parallel()

			root := NewRootCmd()
